        int cnt[10]{};
        int s = 0;
        for (char& c : num) {
            ++cnt[c - '0'];
            s += c - '0';
        }
        if (s % 2) {
            return 0;
        }
        int n = num.size();
        int m = n / 2 + 1;
        int f[10][s / 2 + 1][m][m + 1];
        memset(f, -1, sizeof(f));
        auto dfs = [&](this auto&& dfs, int i, int j, int a, int b) -> int {
            if (i > 9) {
                return ((j | a | b) == 0 ? 1 : 0);
            }
            if (a == 0 && j) {
                return 0;
            }
            if (f[i][j][a][b] != -1) {
                return f[i][j][a][b];
            }
            int ans = 0;
            for (int l = 0; l <= min(cnt[i], a); ++l) {
                int r = cnt[i] - l;
                if (r >= 0 && r <= b && l * i <= j) {
                    int t = c[a][l] * c[b][r] % MOD * dfs(i + 1, j - l * i, a - l, b - r) % MOD;
                    ans = (ans + t) % MOD;
                }
            }
            return f[i][j][a][b] = ans;
        };
        return dfs(0, s / 2, n / 2, (n + 1) / 2);
    }
