		if a == 0 && j > 0 {
			return 0
		}
		if f[i][j][a][b] != -1 {
			return f[i][j][a][b]
		}
		ans := 0
		for l := 0; l <= min(cnt[i], a); l++ {
			r := cnt[i] - l
			if r >= 0 && r <= b && l*i <= j {
				t := c[a][l] * c[b][r] % MOD * dfs(i+1, j-l*i, a-l, b-r) % MOD
				ans = (ans + t) % MOD
			}
		}
		f[i][j][a][b] = ans
		return ans
	}

	return dfs(0, s/2, n/2, (n+1)/2)
}

