					res++
				}
			}
		}

		return res
	}

	for i := 1; i <= n; i++ {
		for j := 0; j < i; j++ {
			a := calc(j, i-1, false)
			b := 1 + calc(j, i-1, true)
			t := min(a, b)
			f[i] = min(f[i], f[j]+t)
